constexpr double kDoorHandoffRightTorsoStartDegrees = -16.0;
constexpr int kDoorHandoffRightTorsoBreakDoorDegrees = 20;
constexpr double kDoorHandoffRightTorsoInitialPerDoorDegree = -0.75;
constexpr double kDoorHandoffRightTorsoFinalPerDoorDegree = 0.00;
constexpr double door_handoff_right_torso_degrees_for_delta(
  const double door_delta_degrees)
{
  constexpr double kInitialSpanDegrees =
    kDoorHandoffRightTorsoBreakDoorDegrees - kDoorHandoffPreopenDegrees;
  const double initial_delta = door_delta_degrees <= kInitialSpanDegrees ?
    door_delta_degrees : kInitialSpanDegrees;
  const double final_delta = door_delta_degrees <= kInitialSpanDegrees ?
    0.0 : door_delta_degrees - kInitialSpanDegrees;
  return kDoorHandoffRightTorsoStartDegrees +
         kDoorHandoffRightTorsoInitialPerDoorDegree * initial_delta +
         kDoorHandoffRightTorsoFinalPerDoorDegree * final_delta;
}
constexpr size_t kDoorHandoffRightRedundancyPrepLayers = 12U;
// Discover the global redundant branch at one-degree spacing, then solve and
// audit every final 0.1-degree target below.  Running both layers at 0.1 degree
// duplicates the expensive beam search without increasing execution density.
constexpr int kDoorHandoffBranchDiscoveryStepsPerDegree = 1;
constexpr size_t kDoorHandoffMovingTargetCount =
  static_cast<size_t>(
  (kDoorHandoffFinalDoorDegrees - kDoorHandoffPreopenDegrees) *
  kDoorHandoffBranchDiscoveryStepsPerDegree + 1);
constexpr size_t kDoorHandoffTargetCount =
  kDoorHandoffRightRedundancyPrepLayers + kDoorHandoffMovingTargetCount;
constexpr int kDoorHandoffRefinementStepsPerDegree = 10;
static_assert(
  kDoorHandoffRefinementStepsPerDegree %
  kDoorHandoffBranchDiscoveryStepsPerDegree == 0);
constexpr size_t kDoorHandoffExecutionMovingTargetCount =
  static_cast<size_t>(
  (kDoorHandoffFinalDoorDegrees - kDoorHandoffPreopenDegrees) *
  kDoorHandoffRefinementStepsPerDegree + 1);
constexpr size_t kDoorHandoffExecutionTargetCount =
  kDoorHandoffRightRedundancyPrepLayers +
  kDoorHandoffExecutionMovingTargetCount;
// The independent q_door=0 takeover starts only after the left-clear recovery
// has physically finished.  Keep its target cardinalities separate from the
// legacy in-process q=3-degree preopen so a zero start can never flow through
// the old unsigned (preopen-1) arithmetic.
constexpr int kDoorHandoffQ0StartDegrees = 0;
constexpr size_t kDoorHandoffQ0MovingTargetCount =
  static_cast<size_t>(
  (kDoorHandoffFinalDoorDegrees - kDoorHandoffQ0StartDegrees) *
  kDoorHandoffBranchDiscoveryStepsPerDegree + 1);
constexpr size_t kDoorHandoffQ0TargetCount =
  kDoorHandoffRightRedundancyPrepLayers +
  kDoorHandoffQ0MovingTargetCount;
constexpr size_t kDoorHandoffQ0ExecutionMovingTargetCount =
  static_cast<size_t>(
  (kDoorHandoffFinalDoorDegrees - kDoorHandoffQ0StartDegrees) *
  kDoorHandoffRefinementStepsPerDegree + 1);
constexpr size_t kDoorHandoffQ0ExecutionTargetCount =
  kDoorHandoffRightRedundancyPrepLayers +
  kDoorHandoffQ0ExecutionMovingTargetCount;
static_assert(kDoorHandoffQ0TargetCount == 73U);
static_assert(kDoorHandoffQ0ExecutionTargetCount == 613U);
constexpr double kDoorHandoffExecutionIntervalSeconds = 0.13;
constexpr double kDoorHandoffFastExecutionIntervalDefaultSeconds = 0.055;
constexpr size_t kExperimentalCandidate3Q0IngressStateCount = 45U;
constexpr size_t kExperimentalCandidate3Q0CoarseStateCount = 73U;
constexpr size_t kExperimentalCandidate3Q0ExactStateCount = 613U;
constexpr size_t kExperimentalCandidate3Q0JointCount = 7U;
constexpr char kExperimentalCandidate3Q0CacheV1Magic[] =
  "H1_DOOR_CANDIDATE3_Q0_EXPERIMENTAL_CACHE_V1";
constexpr char kExperimentalCandidate3Q0CacheV1EndMagic[] =
  "END_H1_DOOR_CANDIDATE3_Q0_EXPERIMENTAL_CACHE_V1";
constexpr char kExperimentalCandidate3Q0CacheMagic[] =
  "H1_DOOR_CANDIDATE3_Q0_EXPERIMENTAL_CACHE_V2";
constexpr char kExperimentalCandidate3Q0CacheEndMagic[] =
  "END_H1_DOOR_CANDIDATE3_Q0_EXPERIMENTAL_CACHE_V2";
