kExperimentalCandidate3Q0JointNames{
  "right_shoulder_pitch_joint", "right_shoulder_roll_joint",
  "right_shoulder_yaw_joint", "right_elbow_joint",
  "right_wrist_roll_joint", "right_wrist_pitch_joint",
  "right_wrist_yaw_joint"};
static_assert(
  kExperimentalCandidate3Q0CoarseStateCount == kDoorHandoffQ0TargetCount);
static_assert(
  kExperimentalCandidate3Q0ExactStateCount ==
  kDoorHandoffQ0ExecutionTargetCount);
// The user explicitly allowed the dense-count requirement to follow the real
// candidate-3 interpolation instead of the former exact-2943 requirement.  A
// shorter, otherwise unchanged branch produced 2809 real samples, so retain a
// user-authorized 2600 lower bound plus exact low/high replay equality.  The
// 0.1-degree / 0.1-mm interpolation limits and every geometric/safety gate
// remain mandatory.
constexpr size_t kDoorHandoffRelaxedMinimumDenseSamples = 2600U;
// This workstation's fully rendered high-poly Gazebo scene runs steadily at
// roughly 0.17--0.26 wall/sim RTF under controller load.  Keep a fresh
// consecutive-sample liveness
// gate for fast simulation trials, while leaving trajectory velocity and
// acceleration audits unchanged.
constexpr double kDoorHandoffFastMinimumRealTimeFactor = 0.12;
constexpr size_t kDoorHandoffFastRealTimeFactorSamples = 5U;
constexpr double kDoorHandoffFastRealTimeFactorNewestMaximumAge = 1.5;
constexpr double kDoorHandoffFastRealTimeFactorWindowMaximumAge = 6.0;
constexpr double kSequentialLeftRetreatPlanningPadding = 0.002;
constexpr double kDoorBodyHingeMaximumRadius = 0.042;
constexpr double kDoorBodyHingeMaximumPenetration = 0.011;
constexpr double kDoorBodyHingeMaximumAbsoluteAxialStation = 0.197;
constexpr size_t kDoorBodyClosedSeatFarRadialTrianglePairs = 43U;

using ExperimentalCandidate3Q0ArmState =
  std::array<double, kExperimentalCandidate3Q0JointCount>;

enum class ExperimentalCandidate3Q0CollisionPolicy
{
  strict,
  non_safety_simulation_right_elbow_torso_allowed,
};

const char * experimental_candidate3_q0_collision_policy_token(
  const ExperimentalCandidate3Q0CollisionPolicy policy)
{
  switch (policy) {
    case ExperimentalCandidate3Q0CollisionPolicy::strict:
      return kExperimentalCandidate3Q0StrictCollisionPolicy;
    case ExperimentalCandidate3Q0CollisionPolicy::
      non_safety_simulation_right_elbow_torso_allowed:
      return kExperimentalCandidate3Q0NonSafetyCollisionPolicy;
  }
  return "INVALID";
}

ExperimentalCandidate3Q0CollisionPolicy
experimental_candidate3_q0_collision_policy(const bool allow_collision)
{
  return allow_collision ?
    ExperimentalCandidate3Q0CollisionPolicy::
    non_safety_simulation_right_elbow_torso_allowed :
    ExperimentalCandidate3Q0CollisionPolicy::strict;
}

struct ExperimentalCandidate3Q0Cache
{
  size_t format_version = 2U;
  ExperimentalCandidate3Q0CollisionPolicy collision_policy =
    ExperimentalCandidate3Q0CollisionPolicy::strict;
  size_t selected_anchor_index = 0U;
  ExperimentalCandidate3Q0ArmState outer_anchor{};
  // The ingress is stored in contact-to-outer order.  Execution reverses it.
  std::vector<ExperimentalCandidate3Q0ArmState> ingress_contact_to_outer;
  std::vector<ExperimentalCandidate3Q0ArmState> coarse;
  std::vector<ExperimentalCandidate3Q0ArmState> exact;
};

bool validate_experimental_candidate3_q0_cache(
  const ExperimentalCandidate3Q0Cache & cache, std::string * error)
{
  if (!error) {
    return false;
  }
  const auto fail = [error](const std::string & message) {
      *error = message;
      return false;
    };
  if (cache.format_version != 1U && cache.format_version != 2U) {
    return fail("cache format version is neither 1 nor 2");
  }
  if (cache.format_version == 1U &&
    cache.collision_policy != ExperimentalCandidate3Q0CollisionPolicy::strict)
  {
    return fail("legacy V1 cache is valid only under the strict collision policy");
  }
  if (std::string(experimental_candidate3_q0_collision_policy_token(
      cache.collision_policy)) == "INVALID")
  {
    return fail("cache collision policy is invalid");
  }
  if (cache.selected_anchor_index > kDoorHandoffRightRedundancyPrepLayers) {
    return fail("selected anchor index is outside the fixed 0..12 range");
  }
  if (cache.ingress_contact_to_outer.size() !=
    kExperimentalCandidate3Q0IngressStateCount ||
    cache.coarse.size() != kExperimentalCandidate3Q0CoarseStateCount ||
    cache.exact.size() != kExperimentalCandidate3Q0ExactStateCount)
  {
    return fail("state counts are not exactly outer=1/ingress=45/coarse=73/exact=613");
  }
  const auto finite_state = [](const ExperimentalCandidate3Q0ArmState & state) {
      return std::all_of(
        state.begin(), state.end(), [](const double value) {
          return std::isfinite(value);
        });
    };
  if (!finite_state(cache.outer_anchor)) {
    return fail("outer anchor contains a non-finite value");
  }
  const auto finite_sequence = [&finite_state, &fail](
    const std::vector<ExperimentalCandidate3Q0ArmState> & states,
    const std::string & label) {
      for (size_t index = 0U; index < states.size(); ++index) {
        if (!finite_state(states[index])) {
          return fail(label + " contains a non-finite value at state " +
                 std::to_string(index));
        }
      }
      return true;
    };
  if (!finite_sequence(cache.ingress_contact_to_outer, "ingress") ||
    !finite_sequence(cache.coarse, "coarse") ||
    !finite_sequence(cache.exact, "exact"))
  {
    return false;
  }
  constexpr double kContinuityRoundoff = 1e-12;
  const auto audit_continuity = [&fail](
    const std::vector<ExperimentalCandidate3Q0ArmState> & states,
    const double limit, const std::string & label) {
      for (size_t state = 1U; state < states.size(); ++state) {
        for (size_t joint = 0U; joint < kExperimentalCandidate3Q0JointCount;
          ++joint)
        {
          const double step = std::abs(
            states[state][joint] - states[state - 1U][joint]);
          if (!std::isfinite(step) || step > limit + kContinuityRoundoff) {
            return fail(
              label + " continuity exceeds its fixed limit at state " +
              std::to_string(state) + ", joint " + std::to_string(joint));
          }
        }
      }
      return true;
    };
  if (!audit_continuity(
      cache.ingress_contact_to_outer, 4.9 * kPi / 180.0, "ingress") ||
    !audit_continuity(cache.coarse, 4.9 * kPi / 180.0, "coarse") ||
    !audit_continuity(cache.exact, 0.49 * kPi / 180.0, "exact"))
  {
    return false;
  }
  const auto audit_exact_seam = [&fail](
    const ExperimentalCandidate3Q0ArmState & first,
    const ExperimentalCandidate3Q0ArmState & second,
    const std::string & label) {
      constexpr double kExactIdentityTolerance = 1e-10;
      for (size_t joint = 0U; joint < kExperimentalCandidate3Q0JointCount;
        ++joint)
      {
        if (std::abs(first[joint] - second[joint]) >
          kExactIdentityTolerance)
        {
          return fail(label + " is not bitwise-close at joint " +
                 std::to_string(joint));
        }
      }
      return true;
    };
  if (!audit_exact_seam(
      cache.outer_anchor, cache.ingress_contact_to_outer.back(),
      "outer/ingress seam") ||
    !audit_exact_seam(
      cache.ingress_contact_to_outer.front(), cache.coarse.front(),
      "ingress/coarse contact seam") ||
    !audit_exact_seam(
      cache.ingress_contact_to_outer.front(), cache.exact.front(),
      "ingress/exact contact seam") ||
    !audit_exact_seam(
      cache.coarse.front(), cache.exact.front(), "coarse/exact start seam"))
  {
    return false;
  }
  error->clear();
  return true;
}

std::optional<ExperimentalCandidate3Q0Cache>
read_experimental_candidate3_q0_cache(
  const std::string & path,
  const ExperimentalCandidate3Q0CollisionPolicy expected_collision_policy,
  std::string * error)
{
  if (!error || path.empty()) {
    return std::nullopt;
  }
  constexpr size_t kMaximumCacheBytes = 512U * 1024U;
  const int descriptor = ::open(
    path.c_str(), O_RDONLY | O_CLOEXEC | O_NOFOLLOW);
  if (descriptor < 0) {
    *error = "cannot safely open cache: " + std::string(std::strerror(errno));
    return std::nullopt;
  }
  struct stat status {};
  if (::fstat(descriptor, &status) != 0 || !S_ISREG(status.st_mode) ||
    status.st_size <= 0 ||
    static_cast<uintmax_t>(status.st_size) > kMaximumCacheBytes)
  {
    const int saved_errno = errno;
    ::close(descriptor);
    *error = "cache is not a nonempty regular file within 512 KiB";
    if (saved_errno != 0) {
      *error += ": " + std::string(std::strerror(saved_errno));
    }
    return std::nullopt;
  }
  std::string contents(static_cast<size_t>(status.st_size), '\0');
  size_t offset = 0U;
  while (offset < contents.size()) {
    const ssize_t count = ::read(
      descriptor, contents.data() + offset, contents.size() - offset);
    if (count < 0 && errno == EINTR) {
      continue;
    }
    if (count <= 0) {
      const int saved_errno = errno;
      ::close(descriptor);
      *error = "cache read ended early";
      if (count < 0) {
        *error += ": " + std::string(std::strerror(saved_errno));
      }
      return std::nullopt;
    }
    offset += static_cast<size_t>(count);
  }
  if (::close(descriptor) != 0) {
    *error = "cache close failed: " + std::string(std::strerror(errno));
    return std::nullopt;
  }

  std::istringstream stream(contents);
  stream.imbue(std::locale::classic());
  const auto expect = [&stream, error](const std::string & expected) {
      std::string actual;
      if (!(stream >> actual) || actual != expected) {
        *error = "expected token '" + expected + "'";
        if (!actual.empty()) {
          *error += ", found '" + actual + "'";
        }
        return false;
      }
      return true;
    };
  ExperimentalCandidate3Q0Cache cache;
  std::string cache_magic;
  if (!(stream >> cache_magic)) {
    *error = "cache magic is missing";
    return std::nullopt;
  }
  if (cache_magic == kExperimentalCandidate3Q0CacheV1Magic) {
    // V1 was produced only by the historical writer whose runtime guard
    // unconditionally rejected the elbow/torso experiment whenever caching
    // was active.  Preserve that installed strict cache without pretending it
    // can carry a relaxed certificate.  Every newly written cache is V2 and
    // records the policy explicitly below.
    cache.format_version = 1U;
    cache.collision_policy = ExperimentalCandidate3Q0CollisionPolicy::strict;
  } else if (cache_magic == kExperimentalCandidate3Q0CacheMagic) {
    cache.format_version = 2U;
    std::string collision_policy_token;
    if (!expect("right_elbow_torso_collision_policy") ||
      !(stream >> collision_policy_token))
    {
      *error = "V2 cache collision-policy metadata is truncated";
      return std::nullopt;
    }
    if (collision_policy_token ==
      kExperimentalCandidate3Q0StrictCollisionPolicy)
    {
      cache.collision_policy =
        ExperimentalCandidate3Q0CollisionPolicy::strict;
    } else if (collision_policy_token ==
      kExperimentalCandidate3Q0NonSafetyCollisionPolicy)
    {
      cache.collision_policy = ExperimentalCandidate3Q0CollisionPolicy::
        non_safety_simulation_right_elbow_torso_allowed;
    } else {
      *error = "V2 cache collision-policy metadata is unknown: " +
        collision_policy_token;
      return std::nullopt;
    }
  } else {
    *error = "cache magic is unsupported: " + cache_magic;
    return std::nullopt;
  }
  if (cache.collision_policy != expected_collision_policy) {
    *error = "cache collision policy '" + std::string(
      experimental_candidate3_q0_collision_policy_token(
        cache.collision_policy)) + "' does not match this run's policy '" +
      experimental_candidate3_q0_collision_policy_token(
        expected_collision_policy) + "'";
    return std::nullopt;
  }
  size_t joint_count = 0U;
  size_t outer_count = 0U;
  size_t ingress_count = 0U;
  size_t coarse_count = 0U;
  size_t exact_count = 0U;
  if (!expect("joint_count") || !(stream >> joint_count) ||
    !expect("outer_count") || !(stream >> outer_count) ||
    !expect("ingress_count") || !(stream >> ingress_count) ||
    !expect("coarse_count") || !(stream >> coarse_count) ||
    !expect("exact_count") || !(stream >> exact_count) ||
    !expect("selected_anchor_index") ||
    !(stream >> cache.selected_anchor_index) || !expect("joint_names"))
  {
    if (error->empty()) {
      *error = "cache header is truncated";
    }
    return std::nullopt;
  }
  if (joint_count != kExperimentalCandidate3Q0JointCount ||
    outer_count != 1U ||
    ingress_count != kExperimentalCandidate3Q0IngressStateCount ||
    coarse_count != kExperimentalCandidate3Q0CoarseStateCount ||
    exact_count != kExperimentalCandidate3Q0ExactStateCount)
  {
    *error = "cache header counts differ from fixed 7/1/45/73/613 contract";
    return std::nullopt;
  }
  for (const char * expected_name : kExperimentalCandidate3Q0JointNames) {
    std::string actual_name;
    if (!(stream >> actual_name) || actual_name != expected_name) {
      *error = "cache joint order differs from the fixed right-arm order";
      return std::nullopt;
    }
  }
  const auto read_state = [&stream, error](
    ExperimentalCandidate3Q0ArmState * state) {
      if (!state) {
        return false;
      }
      for (double & value : *state) {
        if (!(stream >> value) || !std::isfinite(value)) {
          *error = "cache state is truncated or non-finite";
          return false;
        }
      }
      return true;
    };
  if (!expect("outer_begin") || !read_state(&cache.outer_anchor) ||
    !expect("outer_end") || !expect("ingress_contact_to_outer_begin"))
  {
    return std::nullopt;
  }
  cache.ingress_contact_to_outer.resize(ingress_count);
  for (auto & state : cache.ingress_contact_to_outer) {
    if (!read_state(&state)) {
      return std::nullopt;
    }
  }
  if (!expect("ingress_contact_to_outer_end") || !expect("coarse_begin")) {
    return std::nullopt;
  }
  cache.coarse.resize(coarse_count);
  for (auto & state : cache.coarse) {
    if (!read_state(&state)) {
      return std::nullopt;
    }
  }
  if (!expect("coarse_end") || !expect("exact_begin")) {
    return std::nullopt;
  }
  cache.exact.resize(exact_count);
  for (auto & state : cache.exact) {
    if (!read_state(&state)) {
      return std::nullopt;
    }
  }
  const char * expected_end_magic = cache.format_version == 1U ?
    kExperimentalCandidate3Q0CacheV1EndMagic :
    kExperimentalCandidate3Q0CacheEndMagic;
  if (!expect("exact_end") || !expect(expected_end_magic))
  {
    return std::nullopt;
  }
  std::string trailing;
  if (stream >> trailing) {
    *error = "cache contains trailing tokens";
    return std::nullopt;
  }
  if (!validate_experimental_candidate3_q0_cache(cache, error)) {
    return std::nullopt;
  }
  return cache;
}

bool write_new_experimental_candidate3_q0_cache(
  const std::string & path, const ExperimentalCandidate3Q0Cache & cache,
  std::string * error)
{
  if (!error || path.empty() ||
    !validate_experimental_candidate3_q0_cache(cache, error))
  {
    return false;
  }
  if (cache.format_version != 2U) {
    *error = "new cache writes require the policy-bound V2 format";
    return false;
  }
  std::ostringstream stream;
  stream.imbue(std::locale::classic());
  stream << std::scientific <<
    std::setprecision(std::numeric_limits<double>::max_digits10);
  stream << kExperimentalCandidate3Q0CacheMagic << '\n'
         << "right_elbow_torso_collision_policy "
         << experimental_candidate3_q0_collision_policy_token(
              cache.collision_policy) << '\n'
         << "joint_count " << kExperimentalCandidate3Q0JointCount << '\n'
         << "outer_count 1\n"
         << "ingress_count " << kExperimentalCandidate3Q0IngressStateCount << '\n'
         << "coarse_count " << kExperimentalCandidate3Q0CoarseStateCount << '\n'
         << "exact_count " << kExperimentalCandidate3Q0ExactStateCount << '\n'
         << "selected_anchor_index " << cache.selected_anchor_index << '\n'
         << "joint_names";
  for (const char * name : kExperimentalCandidate3Q0JointNames) {
    stream << ' ' << name;
  }
  stream << "\nouter_begin\n";
  const auto write_state = [&stream](
    const ExperimentalCandidate3Q0ArmState & state) {
      for (size_t joint = 0U; joint < state.size(); ++joint) {
        if (joint != 0U) {
          stream << ' ';
        }
        stream << state[joint];
      }
      stream << '\n';
    };
  write_state(cache.outer_anchor);
  stream << "outer_end\ningress_contact_to_outer_begin\n";
  for (const auto & state : cache.ingress_contact_to_outer) {
    write_state(state);
  }
  stream << "ingress_contact_to_outer_end\ncoarse_begin\n";
  for (const auto & state : cache.coarse) {
    write_state(state);
  }
  stream << "coarse_end\nexact_begin\n";
  for (const auto & state : cache.exact) {
    write_state(state);
  }
  stream << "exact_end\n" << kExperimentalCandidate3Q0CacheEndMagic << '\n';
  if (!stream.good()) {
    *error = "cache text serialization failed";
    return false;
  }
  const std::string bytes = stream.str();
  const int descriptor = ::open(
    path.c_str(), O_WRONLY | O_CREAT | O_EXCL | O_CLOEXEC | O_NOFOLLOW,
    S_IRUSR | S_IRGRP | S_IROTH);
  if (descriptor < 0) {
    *error = "refused to create cache (target must not exist): " +
      std::string(std::strerror(errno));
    return false;
  }
  size_t offset = 0U;
  bool passed = true;
  while (offset < bytes.size()) {
    const ssize_t count = ::write(
      descriptor, bytes.data() + offset, bytes.size() - offset);
    if (count < 0 && errno == EINTR) {
      continue;
    }
    if (count <= 0) {
      passed = false;
      *error = "cache write failed: " + std::string(std::strerror(errno));
      break;
    }
    offset += static_cast<size_t>(count);
  }
  if (passed && ::fsync(descriptor) != 0) {
    passed = false;
    *error = "cache fsync failed: " + std::string(std::strerror(errno));
  }
  if (::close(descriptor) != 0 && passed) {
    passed = false;
    *error = "cache close failed: " + std::string(std::strerror(errno));
  }
  if (!passed) {
    ::unlink(path.c_str());
    return false;
  }
  error->clear();
  return true;
}

// PlanningSceneInterface::removeCollisionObjects() publishes an asynchronous
// diff.  This demo repeatedly removes and immediately re-adds the same exact
// incubator objects, so a late REMOVE can otherwise overtake the synchronous
// ADD and make the audited STL disappear.  Keep the established call sites,
// but make every world removal a synchronous /apply_planning_scene update.
class SynchronousPlanningSceneInterface final
  : public moveit::planning_interface::PlanningSceneInterface
{
public:
  using moveit::planning_interface::PlanningSceneInterface::PlanningSceneInterface;

  bool removeCollisionObjects(const std::vector<std::string> & object_ids)
  {
    const auto present_world_objects = getObjects(object_ids);
    std::vector<moveit_msgs::msg::CollisionObject> removals;
    removals.reserve(present_world_objects.size());
    for (const auto & id : object_ids) {
      if (present_world_objects.find(id) == present_world_objects.end()) {
        continue;
      }
      moveit_msgs::msg::CollisionObject removal;
      removal.header.frame_id = kPlanningFrame;
      removal.id = id;
      removal.operation = moveit_msgs::msg::CollisionObject::REMOVE;
      removals.push_back(std::move(removal));
    }
    if (removals.empty()) {
      return true;
    }
    if (!applyCollisionObjects(removals)) {
      RCLCPP_ERROR(
        rclcpp::get_logger("incubator_door_open_demo"),
        "Synchronous planning-scene world-object removal failed.");
      return false;
    }
    return true;
  }
};

